// Traced icons ported from the mobile app's asset set
// (apps/mobile/src/assets/icons). They inherit color via currentColor,
// exactly like the RN versions. Regenerate with the gen-traced-icons script
// rather than editing path data by hand.
import type { ReactNode, SVGProps } from "react";

export type TracedIconProps = SVGProps<SVGSVGElement> & { size?: number };

function frame(size: number, viewBox: string, children: ReactNode, props: TracedIconProps) {
  return (
    <svg width={size} height={size} viewBox={viewBox} aria-hidden="true" {...props}>
      {children}
    </svg>
  );
}

